	{
		copies++;
		anim = anim->m_sibling_anim;
	}

	if (!anim->Running())
		return anim;

	if (!anim->m_auto_copy_anim)
		return NULL;

	u32 max = m_max_anim_copies;

	if (max != 0 && (u32)copies >= max)
		return NULL;

